import copy,hashlib,json
from pathlib import Path
p=Path('Examtopics/audit');s=Path('CCNA-App/app/src/main/assets/data/ccna_cards_data.js').read_text(encoding='utf-8');qs=json.loads(s[s.index('['):].strip().rstrip(';'));by={q['id']:q for q in qs}
data={}
def dnd(n,replacements,prompt,explanation):
 q=by[n];d=copy.deepcopy(q['drag_drop_data']);d['sources']=[replacements.get(x,x) for x in d['sources']]
 for t in d['targets']:t['expected']=replacements.get(t['expected'],t['expected'])
 data[n]={'prompt':prompt,'drag_drop_data':d,'explanation':explanation,'answer_image':None}
base='Classify the adapted characteristics into the two shown categories. Items in the same category may be placed in either order.'
dnd(1171,{'is easy to tap into and obtain secure information':'twisted-pair copper is susceptible to electromagnetic interference','attenuation increases over long distances':'multimode fiber commonly uses a 50 or 62.5 micrometer core','is comprised of shielded and unshielded twisted pairs':'twisted-pair copper is available in shielded and unshielded forms','vulnerable to damage when handled':'glass fiber can be damaged by excessive bending'},base+' Compare twisted-pair copper with typical multimode glass fiber.','铜双绞线可分为屏蔽和非屏蔽类型，且会受电磁干扰；多模光纤常见 50 或 62.5 微米芯径，过度弯曲可能损伤光纤。原图的“距离越长衰减越大”和“不当操作可能损坏”对多种介质均成立，已改为限定性描述。光纤及铜线都需要正确施工；光纤也可能被窃听。每类内顺序不限。')
dnd(1172,{'publicly routable in the same way as IPv4 addresses':'a globally scoped unicast prefix can be advertised on the public Internet','routable and reachable via the Internet':'identifies a single interface with global scope','sends packets to a group address rather than a single address':'identifies a group of interfaces as the packet destination','never used as a source address':'must not be used as an IPv6 packet source'},base+' Compare IPv6 global unicast with multicast.','全局单播地址标识一个接口，具全球作用域；全球作用域本身不保证公网连通，仍需路由与策略，文档前缀等也不能作为公网可达例证。组播地址标识接收组，只能作目的地址，不能作源地址。原图关于“必定互联网可达”的描述过于绝对，已限定；每类内顺序不限。')
dnd(1173,{'makes forwarding decisions when in LWAP mode':'provides the wireless radio interface for client devices','formats an Ethernet frame and forwards to a destination':'every wireless AP always requires a hardware WLC','used on-premise and/or cloud-based':'a controller can be deployed on premises or as a supported virtual instance'},base+' Assign two characteristics to an AP and two to a wireless LAN controller; one option is unused.','AP 提供无线射频接入，并可桥接 IEEE 802.11 与以太网；WLC 可集中管理 AP 并下发安全策略，控制器可按产品支持情况采用本地或虚拟部署。原图将轻量 AP 一概描述为独立决定转发容易误导：集中交换 WLAN 的数据经控制器，FlexConnect 本地交换由 AP 本地转发。独立 AP 不一定需要硬件 WLC。各类别内顺序不限。')
dnd(1174,{'supplies conduit for PoE implementations':'twisted-pair copper can carry Ethernet Power over Ethernet','easy to tap into and obtain secure information':'copper twisted-pair is susceptible to electromagnetic interference','used for DWDM optical systems spanning long distances':'single-mode fiber is commonly used for long-distance DWDM','has a core diameter of 9 microns':'typical single-mode fiber has a core diameter near 9 micrometers'},base+' Compare twisted-pair copper with typical single-mode glass fiber.','PoE 可通过符合标准的铜双绞线传输电力，铜缆受电磁干扰；单模光纤常见约 9 微米芯径，可用于长距离 DWDM，具体容量和距离取决于光模块及链路设计。原图将铜缆一概称为容易获取安全信息过于绝对，窃听风险取决于物理与加密防护。每类内可交换顺序。')
repl={'fe80:efae:0b2a:56fe:4a87:147f:dc21:7':'fe80::4a87:147f:dc21:7','ff00:3b64:fbca:171a:6140:6a35:1ea6:12':'ff02::1','fc00:733d:b542:a948:d7fa:eeea:989a:3':'fd00:733d:b542:a948:d7fa:eeea:989a:3','2000:e2a1:a1ee:03ed:39a0:4f8e:9f02:1':'2001:4860:4860::8888'}
dnd(1175,repl,'Classify each adapted IPv6 address by type.','`2001:4860:4860::8888` 为全局单播格式；`fe80::4a87:147f:dc21:7` 为链路本地单播；`fd00:733d:b542:a948:d7fa:eeea:989a:3` 为本地生成 ULA；`ff02::1` 为链路本地范围组播。原图的 FE80 地址前 64 位保留段非零，FF00 的组播范围为保留值，FC00 的 L 位为 0 而非本地生成 ULA；已改为有效示例。地址格式不保证公网可达。')
dnd(1176,{'affected by electrical and magnetic interference':'twisted-pair copper is affected by electromagnetic interference','easy to tap into and obtain secure information':'twisted-pair copper can carry electrical power using PoE','increased refraction between cladding and core as it travels':'multimode fiber supports multiple optical propagation modes','transmits signals using pulses of light':'multimode fiber transmits information using light pulses'},base+' Compare twisted-pair copper with multimode fiber.','铜双绞线可受到电磁干扰，也可按 PoE 标准承载电力；多模光纤以光脉冲传输，允许多种传播模式。原图所谓“折射增加”不是可靠分类描述，窃听难度也不构成绝对安全保证；光纤同样需要物理和加密防护。每组内部可以互换。')
data[1177]={'prompt':'Configure SW-2 and SW-3 Ethernet0/0 as 802.1Q trunks allowing VLANs 10 and 11, with VLAN 11 native and VLAN 10 tagged. Configure Ethernet0/2 and Ethernet0/3 as a trunk EtherChannel allowing all VLANs, using LACP passive on SW-2 and active on SW-3. The designated channel-group number and topology are not provided; use the actual lab assignment.','answer_image':None,'explanation':'原答案图属于前一题的光纤分类，且当前材料缺少本题拓扑及指定聚合组号；不能凭空确定组号。以下示例中的 `<N>` 必须替换为题目实际指定的本地组号，并确保 VLAN 10/11 存在。根据设备型号，仅在支持且需要时配置 `switchport trunk encapsulation dot1q`。\n\n```text\n! 在两台交换机分别配置\ninterface ethernet 0/0\n switchport mode trunk\n switchport trunk native vlan 11\n switchport trunk allowed vlan 10,11\n no shutdown\n! SW-2 的成员端口使用 passive；SW-3 将 passive 替换为 active\ninterface range ethernet 0/2 - 3\n channel-group <N> mode passive\n no shutdown\ninterface port-channel <N>\n switchport mode trunk\n switchport trunk allowed vlan all\n```\n`<N>` 是占位符而不是可直接执行的命令；核对两端链路、VLAN/native 和通道兼容性。用 `show etherchannel summary`、`show interfaces trunk` 验证；如要求保存，执行 `copy running-config startup-config`。未进行真实设备实验。'}
dnd(1178,{'serves as the next-hop addresses in IGP':'used as the next hop by some IPv6 IGPs on a link','has a unicast source sent to a group':'identifies a group of receiving interfaces in the destination field','never used as a source address':'must not appear as the IPv6 source address','confined to a single link':'link-local addresses are not routed to another link'},base+' Compare IPv6 link-local unicast and multicast destinations.','链路本地地址用于同一链路，不跨路由器转发；OSPFv3 等 IPv6 路由协议可用邻居链路本地地址作为下一跳，但并非所有 IGP 或所有实现均使用。组播目的地址标识接收组，组播地址不能作源地址；某些报文如重复地址检测可使用未指定源地址，不能声称所有组播报文源必为单播。每类内可互换。')
data[1179]={'prompt':'Refer to the displayed routing entries. Assuming the Cisco default administrative distances shown have not been changed, associate each displayed prefix with its route source; one prefix is unused.','explanation':'图中路由条目的来源代码不可见，但括号内显示管理距离：`207.165.200.244/30 [1/1]` 对应默认静态；`192.168.2.0/24 [90/3184437]` 对应默认内部 EIGRP；`192.168.1.0/24 [110/84437]` 对应默认 OSPF；`172.16.2.0/24 [120/2]` 对应默认 RIP。`207.165.200.248/30` 显示为直连，并非四个所选方法。AD 可被管理员修改，因此仅在题设默认值下可由这些数字推断协议；静态路由也可结合跟踪机制撤销，不应一概说不能自动响应变化。'}
data[1180]={'prompt':'For 16 sites, divide 10.20.0.0/16 into 16 equal subnets and use the second subnet: assign the first and last usable IPv4 addresses to Sw101 and Sw102 e0/0 respectively. Divide 2001:db8::/52 into 16 equal /56 site prefixes and assign unique 64-bit interface identifiers from a /64 within the second site prefix to each e0/0. The example uses documentation-only IPv6 space; assume routed interfaces and IPv6 support.','image':by[1180]['answer_image'],'answer_image':None,'explanation':'**IPv4：** 借 4 位得 /20；按从零开始编号，第二个为 `10.20.16.0/20`，范围到 `10.20.31.255`，两端可用地址分别为 `10.20.16.1` 和 `10.20.31.254`，掩码 `255.255.240.0`。\n\n**IPv6：** `/52` 划为 16 个 `/56`，第二个为 **`2001:db8:0:100::/56`**（不是 `2001:db8:100::/56`，后者在不同 /52 中）。选该站点内 `2001:db8:0:100::/64` 作为此链路。`2001:db8::/32` 为文档前缀，不可当作公网部署地址。示例使用两个显式且不同的 64 位接口标识；如平台及任务要求 EUI-64，可在确认接口支持和 MAC 唯一后使用。\n\n```text\n! Sw101，前提：e0/0 为可配置 IP 的三层端口\ninterface ethernet 0/0\n ip address 10.20.16.1 255.255.240.0\n ipv6 address 2001:db8:0:100::1/64\n no shutdown\n! Sw102，同样前提\ninterface ethernet 0/0\n ip address 10.20.31.254 255.255.240.0\n ipv6 address 2001:db8:0:100::2/64\n no shutdown\n```\n若是可转换的交换机端口，按平台要求先配置 `no switchport`；纯二层端口需采用受支持的三层接口/SVI 方案。图中的 e0/0 直接互连；用 `show ip interface brief`、`show ipv6 interface brief` 和双向 ping 验证，必要时保存配置。题目拓扑原来误放在答案图位置，已移回题目区。'}
refs=['https://www.rfc-editor.org/rfc/rfc4291.html','https://www.rfc-editor.org/rfc/rfc4193.html','https://www.rfc-editor.org/rfc/rfc3849.html','https://www.cisco.com/c/en/us/td/docs/wireless/controller/8-7/config-guide/b_cg87/m_flexconnect_overview.html','https://www.cisco.com/c/en/us/td/docs/switches/lan/c9000/lyr2-fwd/etherchannel/etherchannel-configuration-guide/m_ethernetchannel.html']
corrections=[]
for n in range(1171,1181):
 q=by[n];fp=hashlib.sha256(json.dumps(q,ensure_ascii=False,sort_keys=True,separators=(',',':')).encode()).hexdigest();corrections.append({'id':n,'before_sha256':fp,'updates':data[n],'reason':f'逐题对照题图、答案图、分组和技术事实，修复 Q{n} 发现的问题。','review':{'prompt':'checked','options':'checked','answer':'checked','explanation':'corrected','image':'viewed' if q.get('image') or q.get('answer_image') else 'none','code_cli':'checked','finding':f'逐项核对图像、判分和解析；详见报告 Q{n}。','references':refs}})
(p/'agent-1171-1180.json').write_text(json.dumps({'scope':'Q1171–Q1180','corrections':corrections,'sources':refs,'limitations':'审查图像、标准和配置示例；未在真实交换机、WLC 或光纤链路测试。'},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
lines=['# Q1171–Q1180 逐题审查','', '已直接检查 18 张原题及答案图，复核选项、答案、解析、CLI、拖拽数据与各组内无序规则。所有图片证据保存在 exhibits/q1171–q1180 的对应文件中。','',
'- Q1171：衰减和弯曲风险不限单种介质，改成明确铜双绞线及多模特征；各两槽组内无序。',
'- Q1172：组播不能作源地址，但全局单播不保证公网可达；更正绝对化并保留两组。',
'- Q1173：轻量 AP 数据转发依集中或本地交换而异；修正含糊选项和解释，保留两组。',
'- Q1174：PoE 与 9 微米单模特征；去除物理窃听绝对化并保留两组。',
'- Q1175：修正链路本地保留位、组播保留范围及本地 ULA 示例，原图作为证据。',
'- Q1176：修正不准确折射描述和铜线必然易被窃听；每类两槽可互换。',
'- Q1177：答案图误为上一题，拓扑与指定聚合组号缺失；删除误图并标注组号占位符，保留 VLAN 11 未标记及 LACP 前提。',
'- Q1178：组播报文源并非一定单播；限定 IGP 下一跳结论，两类组内可乱序。',
'- Q1179：对照路由表 AD 1/90/110/120，假定默认 AD 才可判断来源；直连前缀为干扰项。',
'- Q1180：正确第二个 /56 为 2001:db8:0:100::/56，修复原错误前缀；将答案区的拓扑移回题干，注明 /64、文档地址与三层接口前提。','', '参考资料：']+['- '+u for u in refs]+['','未进行物理设备或网络实验。']
(p/'agent-1171-1180.md').write_text('\n'.join(lines)+'\n',encoding='utf-8');print('prepared ten fingerprinted corrections and report')
